const contacts = Array.isArray(input.contacts) ? input.contacts : [];

// Only include contacts that actually have an email — we can't look up by email if there isn't one
const withEmail = contacts.filter(c => {
    const props = c && c.properties ? c.properties : c; // handles nested OR flat, just in case
    return props && props.email && String(props.email).trim() !== "";
});

const inputs = withEmail.map(c => {
    const props = c.properties ? c.properties : c;
    return { id: String(props.email).trim().toLowerCase() };
});

return {
    bodyString: JSON.stringify({ idProperty: "email", inputs: inputs }),
    count: inputs.length
};

const contacts = Array.isArray(input.contacts) ? input.contacts : [];
const existingResults = (input.existingRead && Array.isArray(input.existingRead.results))
    ? input.existingRead.results : [];

// Build a lookup: email -> MTMC contact ID, for anyone MTMC already has
const existingByEmail = {};
for (const r of existingResults) {
    const em = (r.properties && r.properties.email ? r.properties.email : "").toLowerCase().trim();
    if (em) existingByEmail[em] = r.id;
}

const toCreate = [];     // brand new contacts
const toAssociate = [];  // MTMC IDs of contacts that already exist

for (const c of contacts) {
    const props = c && c.properties ? c.properties : c; // handles nested OR flat
    const email = (props.email ? String(props.email) : "").toLowerCase().trim();

    if (email && existingByEmail[email]) {
        // Already exists on MTMC — just remember the ID to link later
        toAssociate.push(existingByEmail[email]);
        continue;
    }

    // New contact (or no email at all) — needs to be created
    const properties = {};
    if (email) properties.email = email;
    if (props.firstname) properties.firstname = String(props.firstname).trim();
    if (props.lastname) properties.lastname = String(props.lastname).trim();
    if (props.phone) properties.phone = String(props.phone);
    if (props.mobilephone) properties.mobilephone = String(props.mobilephone);
    if (props.jobtitle) properties.jobtitle = String(props.jobtitle);

    toCreate.push({ properties: properties });
}

return {
    createBodyString: JSON.stringify({ inputs: toCreate }),
    createCount: toCreate.length,
    associateIds: toAssociate,
    associateCount: toAssociate.length
};

const rawCreated = input.createdContacts;
const created = Array.isArray(rawCreated)
    ? rawCreated
    : (rawCreated && Array.isArray(rawCreated.results) ? rawCreated.results : []);

const existing = Array.isArray(input.existingIds) ? input.existingIds : [];

const createdIds = created.map(c => c.id);

const merged = [...new Set([...createdIds, ...existing])];

return {
    allContactIds: merged,
    count: merged.length
};
